const compare = (a, b) => {
  if (typeof a !== "string" || typeof b !== "string") return a < b ? -1 : 1;
  let left = 0, right = 0;
  while (left < a.length && right < b.length) {
    const l = a.codePointAt(left), r = b.codePointAt(right);
    if (l !== r) return l - r;
    left += l > 0xffff ? 2 : 1;
    right += r > 0xffff ? 2 : 1;
  }
  return (a.length - left) - (b.length - right);
};
